{
  "assessments": [
    {
      "proposition_id": "P1",
      "status": "full",
      "summary_quote": "Subject to an appropriation, the bill would require the state department to provide each local education agency (LEA) enough additional funding to employ one full-time licensed professional school counselor at each of its high schools enrolling at least 600 students in grades 10 through 12.",
      "rationale": "Conveys the department’s funding obligation, appropriation condition, counselor qualifications, and school enrollment threshold."
    },
    {
      "proposition_id": "P2",
      "status": "full",
      "summary_quote": "An LEA could use the money to make an existing part-time counselor full-time; doing so would meet the staffing requirement.",
      "rationale": "Conveys the permitted conversion and its satisfaction of the staffing requirement, with the eligible schools and counselor qualifications established in the preceding sentence."
    },
    {
      "proposition_id": "P3",
      "status": "full",
      "summary_quote": "An LEA that already employs one full-time counselor for every 250 student members could use the funding to cover the cost of counselors needed to meet that ratio, and would not have to hire additional counselors beyond that number.",
      "rationale": "Conveys the existing staffing ratio condition and permission to cover the costs of counselors needed to meet it."
    },
    {
      "proposition_id": "P4",
      "status": "partial",
      "summary_quote": "An LEA that already employs one full-time counselor for every 250 student members could use the funding to cover the cost of counselors needed to meet that ratio, and would not have to hire additional counselors beyond that number.",
      "rationale": "Fully conveys the ratio-based exception, but the summary does not clearly state the separate obligation for each LEA to employ a counselor at every high school for which it receives funding."
    },
    {
      "proposition_id": "P5",
      "status": "full",
      "summary_quote": "The funding would be in addition to the LEA’s funding for TISA.",
      "rationale": "Expressly states that the funding supplements TISA allocations."
    },
    {
      "proposition_id": "P6",
      "status": "partial",
      "summary_quote": "The State Board of Education would have authority to set additional roles and responsibilities for counselors funded under the bill.",
      "rationale": "Conveys discretionary authority to establish additional duties for funded counselors, but omits consultation with the department and does not identify existing statutory duties as the baseline."
    },
    {
      "proposition_id": "P7",
      "status": "partial",
      "summary_quote": "It would be required to set how much time those counselors must spend on specified counseling and guidance services and any additional duties set by the board. At least 70% of each counselor’s time would have to be spent working directly with high school students.",
      "rationale": "Conveys mandatory time-allocation rules and the 70% direct-service minimum, but omits departmental consultation and the required preventative and developmental services and selection of one or more listed counseling and guidance services."
    },
    {
      "proposition_id": "P8",
      "status": "full",
      "summary_quote": "The bill would not itself appropriate money; no funds could be committed or spent under it unless the General Assembly specifically appropriated them.",
      "rationale": "Conveys both the absence of an appropriation and the restriction on obligating or spending funds without a specific legislative appropriation."
    },
    {
      "proposition_id": "P9",
      "status": "full",
      "summary_quote": "The rulemaking provisions would take effect when the bill became law.",
      "rationale": "Correctly conveys the immediate effective date for rulemaking purposes."
    },
    {
      "proposition_id": "P10",
      "status": "full",
      "summary_quote": "The other provisions would take effect July 1, 2025, and apply beginning with the 2025–2026 school year.",
      "rationale": "Conveys the effective date for other purposes and ongoing application starting with the specified school year."
    }
  ]
}
